// Parse JSON
const input = items[0].json.text;
const musicUrl = $('6. Quality Check2').first().json.music_url;
let data;

const pexelsMap = {
  brain: 'neural network abstract', mind: 'galaxy mind', think: 'person thinking silhouette',
  thought: 'abstract light rays', dream: 'surreal dream', abstract: 'abstract geometric 3d',
  light: 'bokeh lights', dark: 'dark moody atmosphere', glitch: 'glitch art video',
  void: 'black void abstract', static: 'tv static noise', hallway: 'dark hallway endless',
  ocean: 'deep ocean dark', space: 'deep space stars', calm: 'calm nature loop'
};

try {
  let clean = input;
  const thinkStart = clean.indexOf('<think>');
  const thinkEnd = clean.indexOf('</think>');
  if (thinkStart !== -1 && thinkEnd !== -1) clean = clean.substring(0, thinkStart) + clean.substring(thinkEnd + 8);
  clean = clean.replace(/```json/g, '').replace(/```/g, '').trim();
  const startIdx = clean.indexOf('{');
  const endIdx = clean.lastIndexOf('}');
  if (startIdx !== -1 && endIdx !== -1) data = JSON.parse(clean.substring(startIdx, endIdx + 1));
} catch(e) { data = null; }

if (!data || !data.scenes || data.scenes.length === 0) {
  data = { scenes: [
    { index: 1, sentence: 'Your mind is more powerful than you think.', visual: 'brain' },
    { index: 2, sentence: 'This is what psychology says.', visual: 'mind' },
    { index: 3, sentence: 'Studies have proven this.', visual: 'abstract' },
    { index: 4, sentence: 'And it changes everything.', visual: 'light' },
    { index: 5, sentence: 'Follow for more psychology facts.', visual: 'calm' }
  ]};
}

data.scenes = data.scenes.slice(0, 6).map(s => {
  const visual = (s.visual || 'abstract').toLowerCase();
  return { ...s, visual: pexelsMap[visual] || visual + ' aesthetic' };
});

return [{ json: { scenes: data.scenes, music_url: musicUrl } }];

// Split scenes
const baseFolder = 'C:\\reddit vids n8n\\satisfying';
const scenes = $('8. JSON Parser2').first().json.scenes;
const musicUrl = $('8. JSON Parser2').first().json.music_url;

return scenes.map((s, i) => {
  const idx = s.index || (i + 1);
  return {
    json: {
      index: idx,
      sentence: s.sentence || 'Something is happening.',
      visual: s.visual || 'abstract',
      base_folder: baseFolder,
      audio_filename: 'audio_' + idx + '.mp3',
      visual_filename: 'scene_' + idx + '_visual.mp4',
      music_url: musicUrl
    }
  };
});

// VIRAL ENGINE 6.1: SIMPLIFIED VERSION
const subreddits = ['psychology', 'todayilearned', 'interestingasfuck', 'Showerthoughts'];
const subreddit = subreddits[Math.floor(Math.random() * subreddits.length)];

const hooks = [
  "Psychology says if you can't stop thinking about someone...",
  "Your brain is lying to you right now.",
  "People who do THIS are secretly genius.",
  "If someone does this, they secretly like you.",
  "The dark truth about your personality."
];

const musicUrls = [
  "https://files.freemusicarchive.org/storage-freemusicarchive-org/music/ccCommunity/Kai_Engel/Satin/Kai_Engel_-_04_-_Interception.mp3",
  "https://files.freemusicarchive.org/storage-freemusicarchive-org/music/WFMU/Broke_For_Free/Slam_Dunks/Broke_For_Free_-_05_-_Something_Elated.mp3"
];

const hook = hooks[Math.floor(Math.random() * hooks.length)];
const musicUrl = musicUrls[Math.floor(Math.random() * musicUrls.length)];
const seed = Math.floor(Math.random() * 999999);

return [{ json: { seed, subreddit, hook, music_url: musicUrl, retry_count: 0 } }];

// FILTER VIRAL POSTS
const MIN_UPVOTES = 3000;
const data = items[0].json;
const seedData = $('0. Chaos Seed5').first().json;

let topic = 'Signs of High Intelligence';
try {
  const children = data.data && data.data.children ? data.data.children : [];
  const posts = children.map(c => c.data).filter(p => p.ups >= MIN_UPVOTES && !p.stickied && !p.over_18).slice(0, 10);
  if (posts.length > 0) {
