// Pick best video from Pexels API response
const loopData = $('Loop Batches7').first().json;
const folder = loopData.base_folder;
const idx = loopData.index;
const visFile = 'scene_' + idx + '_visual.mp4';

const pexelsData = items[0].json;
const videos = pexelsData.videos || [];

let cmd;
if (videos.length > 0) {
  const pick = videos[Math.floor(Math.random() * videos.length)];
  const videoFiles = pick.video_files || [];
  const hdVideo = videoFiles.find(f => f.quality === 'hd' && f.width >= 720) || videoFiles[0];
  const url = hdVideo ? hdVideo.link : null;

  if (url) {
    cmd = 'powershell -Command "Invoke-WebRequest -Uri \'' + url + '\' -OutFile \'' + folder + '\\\\' + visFile + '\'"';
  } else {
    cmd = 'ffmpeg -y -f lavfi -i "color=c=purple:s=720x1280:d=6" -c:v libx264 -pix_fmt yuv420p "' + folder + '\\\\' + visFile + '"';
  }
} else {
  cmd = 'ffmpeg -y -f lavfi -i "color=c=purple:s=720x1280:d=6" -c:v libx264 -pix_fmt yuv420p "' + folder + '\\\\' + visFile + '"';
}

return [{ json: { ...loopData, download_cmd: cmd, visual_filename: visFile } }];

// Prep merge command
let d = items[0].json;
if (!d.base_folder) d = { ...d, ...$('Loop Batches7').first().json };

const folder = d.base_folder || 'C:\\\\reddit vids n8n\\\\satisfying';
const visual = folder + '\\\\' + d.visual_filename;
const audio = folder + '\\\\' + d.audio_filename;
const output = folder + '\\\\part_' + (d.index || 1) + '.mp4';

const cmd = 'ffmpeg -y -stream_loop -1 -i "' + visual + '" -i "' + audio + '" -map 0:v -map 1:a -vf "scale=720:1280:force_original_aspect_ratio=increase,crop=720:1280,setsar=1:1,eq=contrast=1.1:brightness=-0.05:saturation=0.9" -c:v libx264 -preset ultrafast -r 30 -c:a aac -shortest "' + output + '"';

return [{ json: { merge_cmd: cmd, folder: folder, music_url: d.music_url } }];
